  out[ja]+="\n// ALEC's original Remote-inspired particle renderer, shared by dashboard and desktop overlay.\n(() => {\n const N=850, TAU=Math.PI*2, clamp=(x,a,b)=>Math.max(a,Math.min(b,x));\n const particles=Array.from({length:N},(_,i)=>{const y=1-2*(i+.5)/N,r=Math.sqrt(1-y*y),a=i*2.39996323;return {x:r*Math.cos(a),y,z:r*Math.sin(a),k:i*.31};});\n window.Roamie.alecOrb = {\n  revision:'ALEC_ORB_NATIVE_V2',\n  paint(ctx,cx,cy,R,st) {\n   if(!ctx||!Number.isFinite(R)||R<=0)return;\n   const mode=st.mode||'idle', level=clamp(Number(st.level)||0,0,1), clock=st.reduced?0:(Number(st.t)||0);\n   const speed=mode==='think'||mode==='execute'?0.75:mode==='talk'||mode==='listen'?0.42:0.18;\n   const p=clock*speed, energy=mode==='talk'||mode==='listen'?level:mode==='think'||mode==='execute'?.8:.13;\n   const breath=1+(st.reduced?0:.015*Math.sin(clock*1.4)),amp=.025+energy*.10;\n   const c=Math.cos(p),sn=Math.sin(p),scale=R/124;\n   ctx.save();ctx.imageSmoothingEnabled=true;\n   const grad=ctx.createRadialGradient(cx,cy,0,cx,cy,R*1.42);\n   grad.addColorStop(0,'rgba(109,118,255,.15)');grad.addColorStop(.65,'rgba(63,88,179,.07)');grad.addColorStop(1,'rgba(5,8,17,0)');\n   ctx.fillStyle=grad;ctx.fillRect(cx-R*1.42,cy-R*1.42,R*2.84,R*2.84);\n   const count=R<32?220:R<60?420:N;\n   const dots=[];\n   for(let i=0;i<count;i++){\n    const a=particles[Math.floor(i*N/count)],x=a.x*c+a.z*sn,z=a.z*c-a.x*sn;\n    const wave=breath*(1+amp*Math.sin(a.k+p*5)+.025*Math.cos(a.y*11+p*3));\n    dots.push({x:cx+x*R*wave,y:cy+a.y*R*wave,z,k:a.k});\n   }\n   dots.sort((a,b)=>a.z-b.z);\n   for(const a of dots){\n    const depth=(a.z+1)/2,hue=mode==='error'?12:210+48*(.5+.5*Math.sin(a.k*.2+p));\n    ctx.fillStyle='hsla('+hue+',90%,'+(58+depth*27)+'%,'+(.12+depth*.77)+')';\n    ctx.beginPath();ctx.arc(a.x,a.y,Math.max(.45,(.65+depth*1.1+energy*.35)*scale),0,TAU);ctx.fill();\n   }\n   for(let k=0;k<4;k++){\n    const turn=p*.2+k*1.05,co=Math.cos(turn),si=Math.sin(turn);\n    ctx.beginPath();\n    for(let j=0;j<=80;j++){\n     const a=j*TAU/80,rr=R*(1.07+k*.045+energy*.06*Math.sin(a*5+p*3+k)),x=Math.cos(a)*rr,y=Math.sin(a)*rr*.75;\n     const xx=cx+x*co-y*si,yy=cy+x*si+y*co;j?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy);\n    }\n    ctx.strokeStyle='rgba(145,172,255,'+(.09+energy*.12)+')';ctx.lineWidth=Math.max(.45,.7*scale);ctx.stroke();\n   }\n   ctx.restore();\n  }\n };\n})();\n";
  rep(pj,"  function home() {","\n  // ALEC live dashboard. No demo data or simulated state in native mode.\n  let alecLive={mode:'idle',level:0,reply:'',microphone:'idle'},alecClock=0,alecLast=0,alecEnergy=0;\n  function alecUpdateLive(m){\n    if(m&&typeof m==='object')alecLive=m;\n    const status=$('alec-orb-status'),reply=$('alec-orb-reply'),listen=$('alec-orb-listen');\n    const labels={idle:'Disponível',listen:'A escutar',think:'A processar',execute:'A executar',talk:'A responder',error:'Atenção',off:'Configurar modelo'};\n    const mode=alecLive.mode==='idle'&&state?.status?.state==='off'?'off':alecLive.mode;\n    if(status)status.textContent=labels[mode]||'Disponível';\n    if(reply)reply.textContent=alecLive.reply||'Escreve uma mensagem ou activa a escuta.';\n    if(listen){listen.textContent=alecLive.microphone==='listening'?'Terminar escuta':'Escutar';listen.disabled=!state?.voice?.on||!state?.voice?.ready;}\n  }\n  function alecOrbLoop(now){\n    requestAnimationFrame(alecOrbLoop);\n    const dt=Math.min(.05,(now-(alecLast||now))/1000);alecLast=now;\n    const canvas=$('alec-main-orb');\n    if(!canvas||document.hidden||!canvas.offsetParent||$('frame').classList.contains('shut'))return;\n    const size=canvas.clientWidth;if(size<2)return;\n    const dpr=Math.min(devicePixelRatio||1,1.5),w=Math.round(size*dpr);\n    if(canvas.width!==w||canvas.height!==w){canvas.width=w;canvas.height=w;}\n    const ctx=canvas.getContext('2d');if(!ctx)return;\n    ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,size,size);\n    alecEnergy+=(Math.max(0,Math.min(1,Number(alecLive.level)||0))-alecEnergy)*Math.min(1,dt*9);\n    if(!REDUCED.matches)alecClock+=dt;\n    window.Roamie.alecOrb?.paint(ctx,size/2,size/2,size*.31,{t:alecClock,mode:alecLive.mode,level:alecEnergy,reduced:REDUCED.matches});\n  }\n  requestAnimationFrame(alecOrbLoop);\n  function alecDashboard(){\n    const mic=btn('Escutar',()=>send({type:'alec_panel_listen'}),{kind:'primary',k:'alec-listen',disabled:!state.voice?.on||!state.voice?.ready});\n    mic.id='alec-orb-listen';\n    const input=el('input',{type:'text',maxLength:4000,placeholder:'Pergunta ao ALEC…','aria-label':'Mensagem ao ALEC','data-k':'alec-ask-text',autocomplete:'off',disabled:!!state.busy});\n    const form=el('form',{className:'alec-compose',on:{submit:e=>{e.preventDefault();const text=input.value.trim();if(!text||state.busy)return;send({type:'alec_panel_ask',text});input.value='';input.blur();}}},input,\n      el('button',{type:'submit',className:'alec-send',textContent:'Enviar',disabled:!!state.busy}));\n    const dashboard=el('div',{className:'alec-dashboard'},\n      el('div',{className:'alec-eyebrow',textContent:'PERSONAL INTELLIGENCE'}),\n      el('div',{className:'alec-orb-wrap'},el('canvas',{id:'alec-main-orb','aria-hidden':'true'})),\n      el('h2',{id:'alec-orb-status',role:'status',textContent:'Disponível'}),\n      el('p',{className:'alec-model-line',textContent:state.model?.name||'Configura um modelo em IA'}),\n      el('div',{className:'alec-main-actions'},mic,btn('Escrever',()=>input.focus(),{k:'alec-write'}),state.busy?btn('Parar',()=>act('stop'),{k:'alec-stop'}):null),\n      form,\n      el('div',{id:'alec-orb-reply',className:'alec-feedback',role:'log','aria-live':'polite',textContent:alecLive.reply||'Escreve uma mensagem ou activa a escuta.'}));\n    queueMicrotask(()=>alecUpdateLive(alecLive));\n    return dashboard;\n  }\n\n  function home() {");
