  out["showcase/panel/alec-theme.css"]+="\n/* ALEC dashboard v2 — the approved particle-orb composition, not the old panel with a palette swap. */\n:root{--side:100px;--gut:18px;--step:10px;--group:18px;--t-head:14px;--t-body:13px;--t-small:11px}\n.frame{background:radial-gradient(ellipse at 66% 31%,#151e35 0%,#070a12 65%);border:1px solid #26324a;border-radius:18px}\n.head{min-height:58px;padding:12px 16px 12px 19px;border-bottom:1px solid #222c40}\n.head .avatar{display:none!important}.head-text .by{letter-spacing:.11em;text-transform:uppercase;font-size:9px}\n.who h1{font-weight:650;letter-spacing:.28em;font-size:21px}.head .led{border-radius:50%;width:7px;height:7px}\n.split{border-top:0;grid-template-columns:var(--side) minmax(0,1fr)}\n.side{padding:10px 6px;border-right:1px solid #222c40;background:#090e19bb}\n.navi{display:flex;flex-direction:column;justify-content:center;gap:4px;min-height:44px;padding:5px 2px;text-align:center;font-size:10px;white-space:normal}\n.navi:before{content:attr(data-alec-icon);font-size:19px;font-weight:400;line-height:1;display:block;letter-spacing:0}\n.navi[aria-current=\"page\"]{--fill:#202a42;--bc:#344365;border-radius:10px}\n.navi .dot{position:absolute;top:5px;right:5px;border-radius:50%}\n.body{padding-inline:18px}.pane:not([hidden]){overflow-y:auto;scrollbar-width:thin}\n.pane .group{border-radius:12px}.pane#pane-home{gap:16px;padding:9px 0 16px;overflow-y:auto}\n.alec-dashboard{display:flex;flex-direction:column;align-items:center;text-align:center;gap:7px;flex:none;padding:8px 0 4px}\n.alec-eyebrow{font-size:10px;letter-spacing:.18em;color:#a4b2cc}\n.alec-orb-wrap{width:min(100%,340px);aspect-ratio:1;position:relative;display:grid;place-items:center;margin:-12px auto -22px;flex:none}\n#alec-main-orb{width:100%;height:100%;display:block;position:relative}\n#alec-orb-status{font:500 23px/1.2 \"Segoe UI\",sans-serif;letter-spacing:.015em;margin:0;color:#eaf2ff}\n.alec-model-line{margin:0;color:#8d9bb3;font-size:11px;max-width:100%;overflow-wrap:anywhere}\n.alec-main-actions{display:flex;justify-content:center;flex-wrap:wrap;gap:8px;margin:7px 0 3px}\n.alec-main-actions .btn{border-radius:12px;min-width:96px;padding:9px 16px;font-size:13px}\n.alec-main-actions .primary{--fill:#c5d2ff;--bc:#c5d2ff;color:#101527}\n.alec-compose{display:flex;width:min(100%,510px);gap:8px;margin:3px auto}\n.alec-compose input{flex:1;min-width:0;border:1px solid #29354d;border-radius:12px;background:#0c111e;color:#eaf2ff;padding:10px 12px;font:13px \"Segoe UI\",sans-serif}\n.alec-send{border:1px solid #364568;border-radius:12px;color:#eaf2ff;background:#172238;padding:9px 14px;font:600 12px \"Segoe UI\",sans-serif;cursor:pointer}\n.alec-send:disabled{opacity:.45;cursor:default}\n.alec-feedback{text-align:left;white-space:pre-wrap;overflow-wrap:anywhere;overflow:auto;max-height:130px;width:min(100%,510px);padding:10px 13px;color:#b8c4da;background:#101622a8;border:1px solid #222c40;border-radius:12px;font-size:12px;line-height:1.6}\n#pane-home.paged>.group.paged{flex:none;min-height:90px}#pane-home .pagebox{flex:none;min-height:64px;max-height:180px;overflow:auto}\n#pane-home>.group:not(.alec-dashboard){border-top:1px solid #222c40;padding-top:12px}\n@media(max-height:620px){.alec-orb-wrap{max-width:250px;margin-top:-6px;margin-bottom:-14px}.alec-dashboard{gap:5px}}\n@media(prefers-reduced-motion:reduce){#alec-main-orb{transition:none}}\n";
